package dev.jarofcucumbers.prscraft;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
class ChannelCodingTest{
 private BitStream flip(BitStream stream,int bit){byte[] bytes=stream.bytes();bytes[bit/8]^=(byte)(1<<(7-bit%8));return new BitStream(bytes,stream.bitLength());}
 @Test void crc32MatchesTheStandardCheckVectorAndDetectsEachSingleBitError(){var plain=BitStream.of("123456789".getBytes(StandardCharsets.US_ASCII));var encoded=ChannelCoding.crcEncode(plain);assertTrue(HexFormat.of().formatHex(encoded.bytes()).endsWith("cbf43926"));assertArrayEquals(plain.bytes(),ChannelCoding.crcDecode(encoded).bytes());for(int bit=0;bit<encoded.bitLength();bit++){var corrupt=flip(encoded,bit);assertThrows(IllegalArgumentException.class,()->ChannelCoding.crcDecode(corrupt));}}
 @Test void hammingCorrectsEverySingleBitPositionForEveryByte(){for(int value=0;value<256;value++){var plain=BitStream.of(new byte[]{(byte)value});var encoded=ChannelCoding.hammingEncode(plain);assertEquals(14,encoded.bitLength());for(int bit=0;bit<14;bit++){var decoded=ChannelCoding.hammingDecode(flip(encoded,bit));assertArrayEquals(plain.bytes(),decoded.stream().bytes());assertEquals(1,decoded.correctedWords());}}}
 @Test void doubleErrorsCanMiscorrectAndCrcRejectsTheResult(){var protectedBits=ChannelCoding.hammingEncode(ChannelCoding.crcEncode(BitStream.of(new byte[]{42,13,7})));var corrupt=flip(flip(protectedBits,0),1);var decoded=ChannelCoding.hammingDecode(corrupt);assertTrue(decoded.correctedWords()>0);assertThrows(IllegalArgumentException.class,()->ChannelCoding.crcDecode(decoded.stream()));}
 @Test void worstCaseCompressionHeadersAndCodingFitAndRoundTrip(){byte[] input=new byte[1024];for(int i=0;i<input.length;i++)input[i]=(byte)i;var compressed=SourceCompression.encode(input,"huffman");var encoded=ChannelCoding.hammingEncode(ChannelCoding.crcEncode(BitStream.of(compressed.bytes())));assertTrue(encoded.bitLength()<=BitStream.MAX_BYTES*8);for(int bit=0;bit<encoded.bitLength();bit+=211)encoded=flip(encoded,bit);var decoded=ChannelCoding.hammingDecode(encoded);assertTrue(decoded.correctedWords()>0);assertArrayEquals(input,SourceCompression.decode(ChannelCoding.crcDecode(decoded.stream()).aligned()));}
 @Test void lengthsAndNonByteAlignedOperationsAreValidated(){var encoded=ChannelCoding.hammingEncode(BitStream.of(new byte[]{1}));assertThrows(IllegalArgumentException.class,encoded::aligned);assertThrows(IllegalArgumentException.class,()->ChannelCoding.hammingDecode(new BitStream(new byte[]{1},7)));assertThrows(IllegalArgumentException.class,()->ChannelCoding.crcDecode(BitStream.of(new byte[3])));assertThrows(IllegalArgumentException.class,()->ChannelCoding.hammingEncode(BitStream.of(new byte[4096])));}
}
